d = [0] * (n + 1)

def bfs(st, sign):
    q = deque()
    q.append((st, 0))
    ans = set()
    ans.add(st)
    d[st] = 0
    while q:
        v, dd = q.popleft()
        for u in g[v]:
            if u not in ans:
                ans.add(u)
                q.append((u, dd + sign))
                d[u] = dd + sign
    return ans

