import sys

n, m = [int(i) for i in input().split()]
sub = [i for i in range(n + 1)]

def find_boss(x):
    while x != sub[x]:
        x = sub[x]
    return x

def union_boss(a, b):
    root_a = find_boss(a)
    root_b = find_boss(b)
    if root_a != root_b:
        sub[root_a] = root_b

