weight_sum = total_weight * k % MOD

factorials = [1] * (n + 1)
inverse = [1] * (n + 1)
for i in range(2, n + 1):
    factorials[i] = factorials[i - 1] * i % MOD
    inverse[i] = pow(factorials[i], MOD - 2, MOD)

def binom(n, k):
    return factorials[n] * inverse[k] % MOD * inverse[n - k] % MOD

def stirling_second(n, k):
    if n == k:
        return 1
    elif k == 1:
        return pow(k, n, MOD)
    else:
        res = 0
        for i in range(k + 1):
            if i % 2 == 0:
                res = (res + binom(k, i) * pow(k - i, n, MOD)) % MOD
            else:
                res = (res - binom(k, i) * pow(k - i, n, MOD)) % MOD
        return res * inverse[k] % MOD

partitions = stirling_second(n, k)
result = (partitions * weight_sum) % MOD

print(result)

MOD = 1000000007

def power(x, y):
    res = 1
    while y > 0:
        if y % 2:
            res = res * x % MOD
        y //= 2
        x = x * x % MOD
    return res

def solve(k):
    dp = [[0] * 31 for _ in range(31)]
    dp[0][0] = 1
    for i in range(1, 31):
        for j in range(1, 31):
            dp[i][j] = (dp[i - 1][j] * j + dp[i - 1][j - 1]) % MOD

    ans = 0
    last = 0
    for i in range(30, -1, -1):
        if k & (1 << i):
            for j in range(1, 31):
                ans = (ans + dp[last + i][j]) % MOD
            last += 1
    ans = (ans + 1) % MOD
    return ans

