def aux(a):
	a = sorted(a, key=lambda x: x[0] - x[1], reverse=True)
	if a[0][0] <= a[0][1]:
		return 0
	res = 1
	cur_sum = a[0][0]
	rem_sum = a[0][1]
	for i in range(1, len(a)):
		if cur_sum + a[i][0] > rem_sum + a[i][1]:
			cur_sum += a[i][0]
			rem_sum += a[i][1]
			res += 1
	return res
