def near(i, n, m):
	x = i // m
	y = i % m
	d = [[0, -1], [0, 1], [-1, 0], [1, 0]]
	ns = []
	for (dx, dy) in d:
		nx = x + dx
		ny = y + dy
		if nx >= 0 and nx < n and (ny >= 0) and (ny < m):
			ns.append(nx * m + ny)
	return ns

def check(p, n, m):
	d = [[0, -1], [0, 1], [-1, 0], [1, 0]]
	for x in range(n):
		for y in range(m):
			ns = near(p[x * m + y], n, m)
			for (dx, dy) in d:
				nx = x + dx
				ny = y + dy
				if nx >= 0 and nx < n and (ny >= 0) and (ny < m) and (p[nx * m + ny] in ns):
					return True
	return False
