def modpow(a, e):
	ret = 1
	while e > 0:
		if e % 2 == 1:
			ret = ret * a % mod
		a = a * a % mod
		e = e // 2
	return ret

def pw(a, e):
	ret = 1
	while e > 0:
		if e % 2 == 1:
			ret *= a
		a *= a
		e = e // 2
	return ret
