import sys
from itertools import chain, permutations

def res(x):
	result = 1
	current = 1
	for i in range(1, len(x)):
		if x[i] > x[i - 1]:
			current = current + 1
			result = max(result, current)
		else:
			result = max(result, current)
			current = 1
		if result < current:
			current = result
	return result

def check(x):
	best = res(x)
	for pos in range(len(x)):
		new = x[:pos] + x[pos + 1:]
		best = max(best, res(new))
	return best
