	t = int(input())
	for i in range(t):
		n = int(input())
		m = [int(s) for s in input().split()]
		d = deque([m[0]])
		for j in range(1, n):
			if m[j] < d[0]:
				d.appendleft(m[j])
			else:
				d.append(m[j])
		print(' '.join((str(s) for s in d)))
solve()

from sys import stdin
from collections import deque

def read_input():
	n = int(stdin.readline())
	p = list(map(int, stdin.readline().split()))
	return (n, p)

def solve(n, p):
	answer = deque()
	for pi in p:
		if len(answer) == 0 or pi < answer[0]:
			answer.appendleft(pi)
		else:
			answer.append(pi)
	return ' '.join(map(str, answer))

def main():
	t = int(stdin.readline())
	for _ in range(t):
		(n, p) = read_input()
		answer = solve(n, p)
		print(answer)
main()

