def solution_e1(l):
	result = []
	aux = [l[0]]
	tmpmin = l[0]
	for x in l[1:]:
		if x < tmpmin:
			tmpmin = x
			aux.append(x)
		else:
			result.append(x)
	return aux[::-1] + result
