from math import inf

def is_increasing_matrix(matrix, r, c):
	for i in range(r):
		for j in range(c):
			top = -1 if i == 0 else matrix[i - 1][j]
			bottom = inf if i == r - 1 else matrix[i + 1][j]
			left = -1 if j == 0 else matrix[i][j - 1]
			right = inf if j == c - 1 else matrix[i][j + 1]
			if not (left < matrix[i][j] < right and top < matrix[i][j] < bottom):
				return False
	return True

def main():
	(r, c) = map(int, input().split())
	matrix = []
	for i in range(r):
		matrix.append(list(map(int, input().split())))
	changed = False
	for i in range(r - 2, 0, -1):
		for j in range(c - 2, 0, -1):
			upper_margin = matrix[i][j + 1] + matrix[i + 1][j] if 0 in [matrix[i][j + 1], matrix[i + 1][j]] else min(matrix[i][j + 1], matrix[i + 1][j])
			lower_margin = max(matrix[i][j - 1], matrix[i - 1][j])
			if lower_margin >= upper_margin - 1:
				print(-1)
				return
			if matrix[i][j] == 0:
				matrix[i][j] = upper_margin - 1
				changed = True
	if not changed:
		if not is_increasing_matrix(matrix, r, c):
			print(-1)
			return
	print(sum([sum(row) for row in matrix]))
main()

import sys
ii = lambda : sys.stdin.readline().strip()
idata = lambda : [int(x) for x in ii().split()]

def solve():
	(n, m) = idata()
	posle_progulki_po_strokam = []
	matrix = []
	summ = 0
	flag = True
	for i in range(n):
		s = idata()
		matrix += [s[:]]
		d = 0
		q = 0
		for j in range(m):
			if s[j] and d:
				if s[j] - q <= d:
					flag = False
				for w in range(d):
					s[j - w - 1] = s[j - w] - 1
				d = 0
				q = s[j]
			elif s[j]:
				if q >= s[j]:
					flag = False
				q = s[j]
			else:
				d += 1
		posle_progulki_po_strokam += [s[:]]
	for i in range(m):
		s = []
		for k in range(n):
			s += [posle_progulki_po_strokam[k][i]]
		s1 = []
		for k in range(n):
			s1 += [matrix[k][i]]
		d = 0
		q = 0
		for j in range(n):
			if s1[j] and d:
				if s1[j] - q <= d:
					flag = False
				for w in range(d):
					s[j - w - 1] = min(s[j - w] - 1, s[j - w - 1])
				if j - d != 0 and s[j - d] <= s[j - d - 1]:
					flag = False
				d = 0
				q = s1[j]
			elif s1[j]:
				if q >= s1[j]:
					flag = False
				q = s1[j]
			else:
				d += 1
		summ += sum(s)
	if not flag:
		print(-1)
		return
	print(summ)
	return
solve()

import sys

def getGreatest(left, right, top, down):
	x = right - 1
	while x != left and x != top:
		if x < right and x > left and (x > top) and (x < down):
			return x
		x -= 1
	return '-1'

def summ(matrix, n, m):
	s = 0
	for i in range(n):
		for j in range(m):
			s += matrix[i][j]
	return s
