class DSU:

	def __init__(self, nodes):
		self.p = [i for i in range(nodes)]
		self.r = [0 for i in range(nodes)]
		self.s = [1 for i in range(nodes)]

	def nonrecurive_get(self, u):
		v = u
		while self.p[v] != v:
			v = self.p[v]
		while self.p[u] != u:
			(u, self.p[u]) = (self.p[u], v)
		return u

	def get(self, u):
		if u != self.p[u]:
			self.p[u] = self.get(self.p[u])
		return self.p[u]

	def union(self, u, v):
		u = self.get(u)
		v = self.get(v)
		if u != v:
			if self.r[u] > self.r[v]:
				(u, v) = (v, u)
			self.p[u] = v
			if self.r[u] == self.r[v]:
				self.r[v] += 1
			self.s[v] += self.s[u]

	def size(self, u):
		u = self.get(u)
		return self.s[u]

def solve():
	n = int(input())
	dsus = [DSU(n), DSU(n)]
	for edge in range(n - 1):
		(x, y, c) = [int(s) for s in input().split(' ')]
		dsus[c].union(x - 1, y - 1)
	return sum([dsus[0].size(v) * dsus[1].size(v) - 1 for v in range(n)])
print(solve())

