def bfs(source, graph, mark, fcount):
	visited = [source]
	q = deque()
	mark[source] = True
	q.append(source)
	while q:
		u = q.popleft()
		for v in graph[u]:
			if not mark[v]:
				mark[v] = True
				visited.append(v)
				q.append(v)
	for u in visited:
		fcount[u] = len(visited)

