			l.append(i)
	ans = list(s)
	if len(l):
		a = l[0] - 1
		while a >= max(0, l[0] - m):
			ans[a] = '1'
			a -= 1
		a = l[-1] + 1
		while a <= min(n - 1, l[-1] + m):
			ans[a] = '1'
			a += 1
		for i in range(len(l) - 1):
			x = l[i + 1] - l[i] - 1
			if x:
