def gcd(a, b):
	if a == 0:
		return (b, 0, 1)
	(g, x1, y1) = gcd(b % a, a)
	y = x1
	x = y1 - b // a * x1
	return (g, x, y)

def comp(da, db, t, a, b):
	ra = a + da * t
	rb = b + db * t
	return ra + rb

