class Union:

	def __init__(self, n, list_k):
		self.p = {i: i for i in range(n + 1)}
		self.rank = {i: 0 for i in range(n + 1)}
		for k in list_k:
			self.rank[k] = 1

	def find(self, x):
		if x < 0:
			return x
		if self.p[x] != x:
			self.p[x] = self.find(self.p[x])
		return self.p[x]

	def union(self, x, y):
		if x < 0 or y < 0:
			return
		x = self.find(x)
		y = self.find(y)
		if x != y:
			if self.rank[x] < self.rank[y]:
				self.p[x] = y
				self.rank[y] += self.rank[x]
			else:
				self.p[y] = x
				self.rank[x] += self.rank[y]
