	(V, H) = ([], [])
	for ii in gg:
		dancer = dancers[ii]
		if dancer[0] == 1:
			V.append(dancer)
		else:
			H.append(dancer)
	V.sort(key=lambda x: -x[1])
	H.sort(key=lambda x: x[1])
	table = {orig: get_dest(new, w, h) for (orig, new) in zip(V + H, H + V)}
	for ii in gg:
		destinations[ii] = table[dancers[ii]]
